import{_ as t,o,c as r,a2 as a}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Advisor — enumerated source for the Azure Advisor recommendations assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/advisor-recommendations.md","filePath":"frameworks/advisor-recommendations.md"}'),d={name:"frameworks/advisor-recommendations.md"};function i(s,e,c,n,m,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="advisor-—-enumerated-source-for-the-azure-advisor-recommendations-assessment" tabindex="-1">Advisor — enumerated source for the Azure Advisor recommendations assessment <a class="header-anchor" href="#advisor-—-enumerated-source-for-the-azure-advisor-recommendations-assessment" aria-label="Permalink to &quot;Advisor — enumerated source for the Azure Advisor recommendations assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Azure Advisor is Microsoft&#39;s own recommendation engine. It analyses resource configuration and usage telemetry and raises recommendations in five categories, each rated High, Medium or Low impact. <code>src/assess/rules/advisor.recommendations.yaml</code> scores <strong>what Advisor reports for the estate</strong>: it does not re-derive Advisor&#39;s findings, it counts them per category and impact, flags service-retirement notices, and checks the Advisor score. It is written against this page only, and every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Source page</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-overview" target="_blank" rel="noreferrer">Introduction to Azure Advisor</a>; <a href="https://learn.microsoft.com/azure/advisor/advisor-azure-resource-graph" target="_blank" rel="noreferrer">Get Advisor recommendations in Azure Resource Graph</a>; <a href="https://learn.microsoft.com/azure/advisor/advisor-score" target="_blank" rel="noreferrer">Advisor score</a>; category references: <a href="https://learn.microsoft.com/azure/advisor/advisor-reference-reliability-recommendations" target="_blank" rel="noreferrer">Reliability</a>, <a href="https://learn.microsoft.com/azure/advisor/advisor-security-recommendations" target="_blank" rel="noreferrer">Security</a>, <a href="https://learn.microsoft.com/azure/advisor/advisor-reference-performance-recommendations" target="_blank" rel="noreferrer">Performance</a>, <a href="https://learn.microsoft.com/azure/advisor/advisor-reference-cost-recommendations" target="_blank" rel="noreferrer">Cost</a>, <a href="https://learn.microsoft.com/azure/advisor/advisor-reference-operational-excellence-recommendations" target="_blank" rel="noreferrer">Operational excellence</a></td></tr><tr><td>Framework version</td><td>Azure Advisor categories (HighAvailability, Security, Performance, Cost, OperationalExcellence) and impact levels (High, Medium, Low) as documented on Microsoft Learn on the extraction date; ARG <code>advisorresources</code> table with the consolidated <code>recommendationStatus</code> field. Advisor is not versioned per recommendation, so the extraction date is the version.</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The overview, Resource Graph, score and category-reference pages were read with the Microsoft Learn MCP <code>microsoft_docs_search</code> and <code>microsoft_docs_fetch</code> tools on 2026-11-25. The category names were confirmed against the Advisor SDK <code>Category</code> enum (HighAvailability, Security, Performance, Cost, OperationalExcellence). The shape of Scout&#39;s <code>advisor[]</code> rows was read from <code>src/ingest/Import-AdvisorScores.ps1</code> and the collection filter from <code>src/collect/Get-ScoutRawInventory.ps1</code>. Rules were NOT run against a live tenant for this page; the repository&#39;s own hand-off notes record a live collection that returned Advisor rows through this path.</td></tr></tbody></table><h2 id="what-scout-already-collects-from-advisor" tabindex="-1">What Scout already collects from Advisor <a class="header-anchor" href="#what-scout-already-collects-from-advisor" aria-label="Permalink to &quot;What Scout already collects from Advisor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dataset</th><th>collect.json path</th><th>Fields</th><th>Notes</th></tr></thead><tbody><tr><td>Recommendations</td><td><code>$.advisor[]</code> (with <code>$.advisorAvailable</code>)</td><td><code>Category</code>, <code>Impact</code>, <code>ImpactedField</code>, <code>ImpactedValue</code>, <code>Subscription</code>, <code>ShortDescriptionProblem</code>, <code>ShortDescriptionSolution</code></td><td>Filled by <code>Import-AdvisorScores</code>. In the normal single-pass path the rows are <code>advisorresources</code> rows filtered to <code>properties.impact in (Medium, High)</code>. <code>advisorAvailable</code> is <code>false</code> when Advisor was skipped or could not be read, which is what turns every Advisor rule into Not assessed.</td></tr><tr><td>Scores</td><td><code>$.management.advisorScores[]</code></td><td><code>id</code>, <code>name</code>, <code>subscriptionId</code>, <code>lastRefreshedScore</code></td><td>From <code>microsoft.advisor/advisorscore</code>. Present on some collection paths only; the rule is gated on the rows existing.</td></tr></tbody></table><p><strong>Category names.</strong> Advisor&#39;s API and Resource Graph call the Reliability category <code>HighAvailability</code>. The rules match that spelling.</p><h2 id="limits-of-the-data-and-the-projection-that-would-remove-each" tabindex="-1">Limits of the data, and the projection that would remove each <a class="header-anchor" href="#limits-of-the-data-and-the-projection-that-would-remove-each" aria-label="Permalink to &quot;Limits of the data, and the projection that would remove each&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Effect on the rules</th><th>What is needed</th></tr></thead><tbody><tr><td>Low-impact recommendations are not collected (the collection filter keeps Medium and High)</td><td>No Low-impact rule can exist; ADVISOR-GOV-02 is Manual</td><td>Remove the <code>properties.impact</code> filter on the <code>Advisories</code> query in <code>Get-ScoutRawInventory.ps1</code>, or read Low separately.</td></tr><tr><td>The recommendation status is not carried</td><td>A recommendation that someone dismissed, postponed or completed still counts toward a Fail</td><td>Add <code>properties.recommendationStatus</code> (values <code>New</code>, <code>InProgress</code>, <code>Completed</code>, <code>Postponed</code>, <code>Dismissed</code>; verified on the Advisor Resource Graph page) to the <code>advisor[]</code> row, and filter rules to <code>New</code> and <code>InProgress</code>.</td></tr><tr><td>The stable recommendation type id is not carried</td><td>Per-recommendation rules (for example &quot;Create an Azure Service Health alert&quot;) cannot key on the id and would have to match text</td><td>Add <code>properties.recommendationTypeId</code> (a GUID per recommendation type; verified on the Resource Graph page) to the row. The category-reference pages above list each type&#39;s id, so rules can then be written per recommendation.</td></tr><tr><td>The recommendation&#39;s resource id is not carried</td><td><code>ImpactedField</code> is the resource type and <code>ImpactedValue</code> is the resource name, so two resources with the same name in different resource groups look alike, and a rule cannot join a recommendation to <code>compute.virtualMachines</code></td><td>Add <code>properties.resourceMetadata.resourceId</code> (verified on the Resource Graph page) to the row.</td></tr><tr><td>The recommendation subcategory is not carried</td><td>Retirement notices (ADVISOR-RE-03) are found by matching the problem text, which can miss a differently worded notice</td><td>Add the subcategory (<code>ServiceUpgradeAndRetirement</code> for retirements, per the Advisor service-retirement guidance). The Resource Graph page reads it as <code>properties.recommendationSubCategory</code> on <code>microsoft.advisor/metadata</code> rows, joined to recommendations on <code>properties.recommendationTypeId</code>; whether the recommendation rows carry it directly is not confirmed.</td></tr><tr><td>Category and impact come from the recommendation row itself</td><td>If a future Resource Graph change moves them off the recommendation row, <code>Category</code> and <code>Impact</code> would read empty and every rule would pass</td><td>The Resource Graph page&#39;s samples take <code>recommendationCategory</code> and <code>recommendationImpact</code> from <code>microsoft.advisor/metadata</code>, joined on <code>properties.recommendationTypeId</code>. Scout&#39;s collected rows carry them directly today, so no change is needed now; a metadata join is the fallback.</td></tr><tr><td>Category-level scores may not be collected</td><td>Only a score-below-threshold check (ADVISOR-SC-01) is possible, not &quot;Reliability score under N&quot;</td><td>Collect the <code>microsoft.advisor/advisorscore/category</code> Resource Graph type (listed in the Resource Graph supported-types reference), or the REST <code>advisorScore</code> list that returns one entity per category.</td></tr></tbody></table><p>None of these projections was run against live Resource Graph output for this page. The property names are as documented on Microsoft Learn.</p><h2 id="the-enumeration-—-15-items-12-automated-3-manual" tabindex="-1">The enumeration — 15 items (12 automated, 3 manual) <a class="header-anchor" href="#the-enumeration-—-15-items-12-automated-3-manual" aria-label="Permalink to &quot;The enumeration — 15 items (12 automated, 3 manual)&quot;">​</a></h2><p>Every Advisor-backed item is <strong>gated</strong> on <code>$.advisorAvailable</code>, so a run that skipped Advisor reports Not assessed instead of a clean pass. A passing result means &quot;Advisor reported nothing at this level for the subscriptions it could read&quot;, not &quot;nothing is wrong&quot;.</p><h3 id="reliability-advisor-category-highavailability-—-3-items" tabindex="-1">Reliability (Advisor category <code>HighAvailability</code>) — 3 items <a class="header-anchor" href="#reliability-advisor-category-highavailability-—-3-items" aria-label="Permalink to &quot;Reliability (Advisor category `HighAvailability`) — 3 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-RE-01</td><td>No High-impact reliability recommendation is open</td><td>✅ <code>$.advisor</code> <code>Category == HighAvailability</code>, <code>Impact == High</code></td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-reference-reliability-recommendations" target="_blank" rel="noreferrer">Reliability recommendations</a></td></tr><tr><td>ADVISOR-RE-02</td><td>No Medium-impact reliability recommendation is open</td><td>✅ <code>Impact == Medium</code></td><td>same</td></tr><tr><td>ADVISOR-RE-03</td><td>No recommendation warns of a service retirement or deprecation</td><td>✅ <code>ShortDescriptionProblem</code> matches retire / deprecate / end of support (text match; see limits)</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-how-to-use-service-upgrade-retirement-recommendations" target="_blank" rel="noreferrer">Use service upgrade and retirement recommendations</a></td></tr></tbody></table><h3 id="security-—-2-items" tabindex="-1">Security — 2 items <a class="header-anchor" href="#security-—-2-items" aria-label="Permalink to &quot;Security — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-SE-01</td><td>No High-impact security recommendation is open</td><td>✅ <code>Category == Security</code>, <code>Impact == High</code></td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-security-recommendations" target="_blank" rel="noreferrer">Security recommendations</a></td></tr><tr><td>ADVISOR-SE-02</td><td>No Medium-impact security recommendation is open</td><td>✅ <code>Impact == Medium</code></td><td>same</td></tr></tbody></table><h3 id="performance-—-2-items" tabindex="-1">Performance — 2 items <a class="header-anchor" href="#performance-—-2-items" aria-label="Permalink to &quot;Performance — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-PE-01</td><td>No High-impact performance recommendation is open</td><td>✅ <code>Category == Performance</code>, <code>Impact == High</code></td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-reference-performance-recommendations" target="_blank" rel="noreferrer">Performance recommendations</a></td></tr><tr><td>ADVISOR-PE-02</td><td>No Medium-impact performance recommendation is open</td><td>✅ <code>Impact == Medium</code></td><td>same</td></tr></tbody></table><h3 id="cost-—-2-items" tabindex="-1">Cost — 2 items <a class="header-anchor" href="#cost-—-2-items" aria-label="Permalink to &quot;Cost — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-CO-01</td><td>No High-impact cost recommendation is open</td><td>✅ <code>Category == Cost</code>, <code>Impact == High</code></td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-reference-cost-recommendations" target="_blank" rel="noreferrer">Cost recommendations</a></td></tr><tr><td>ADVISOR-CO-02</td><td>No Medium-impact cost recommendation is open</td><td>✅ <code>Impact == Medium</code></td><td>same</td></tr></tbody></table><h3 id="operational-excellence-—-2-items" tabindex="-1">Operational excellence — 2 items <a class="header-anchor" href="#operational-excellence-—-2-items" aria-label="Permalink to &quot;Operational excellence — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-OE-01</td><td>No High-impact operational excellence recommendation is open</td><td>✅ <code>Category == OperationalExcellence</code>, <code>Impact == High</code></td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-reference-operational-excellence-recommendations" target="_blank" rel="noreferrer">Operational excellence recommendations</a></td></tr><tr><td>ADVISOR-OE-02</td><td>No Medium-impact operational excellence recommendation is open</td><td>✅ <code>Impact == Medium</code></td><td>same</td></tr></tbody></table><h3 id="advisor-score-—-1-item" tabindex="-1">Advisor score — 1 item <a class="header-anchor" href="#advisor-score-—-1-item" aria-label="Permalink to &quot;Advisor score — 1 item&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-SC-01</td><td>No Advisor score is below 70 percent</td><td>✅ <code>$.management.advisorScores</code> <code>lastRefreshedScore</code> (<strong>70 is Scout&#39;s threshold; Microsoft publishes no pass mark</strong>)</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-score" target="_blank" rel="noreferrer">Advisor score</a></td></tr></tbody></table><h3 id="governance-of-the-recommendation-backlog-—-3-items" tabindex="-1">Governance of the recommendation backlog — 3 items <a class="header-anchor" href="#governance-of-the-recommendation-backlog-—-3-items" aria-label="Permalink to &quot;Governance of the recommendation backlog — 3 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>ADVISOR-GOV-01</td><td>Postponed and dismissed recommendations carry a recorded reason and a review date</td><td>❌ Manual — status not collected</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-azure-resource-graph" target="_blank" rel="noreferrer">Advisor in Resource Graph</a></td></tr><tr><td>ADVISOR-GOV-02</td><td>Low-impact recommendations are reviewed on a schedule</td><td>❌ Manual — Low impact not collected</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-overview" target="_blank" rel="noreferrer">Introduction to Advisor</a></td></tr><tr><td>ADVISOR-GOV-03</td><td>Advisor recommendation alerts are routed to an action group</td><td>❌ Manual — activity-log alert rules attached (estate-wide)</td><td><a href="https://learn.microsoft.com/azure/advisor/advisor-overview" target="_blank" rel="noreferrer">Introduction to Advisor</a></td></tr></tbody></table><h2 id="how-this-relates-to-the-other-scout-assessments-that-read-advisor" tabindex="-1">How this relates to the other Scout assessments that read Advisor <a class="header-anchor" href="#how-this-relates-to-the-other-scout-assessments-that-read-advisor" aria-label="Permalink to &quot;How this relates to the other Scout assessments that read Advisor&quot;">​</a></h2><p><code>waf.cost.yaml</code>, <code>waf.security.yaml</code>, <code>waf.performance.yaml</code>, <code>finops.review.yaml</code> and <code>caf.govern.cm.yaml</code> each read <code>$.advisor</code> for one category and impact as part of a WAF pillar or FinOps score. This assessment is the complete, category-by-category view of the same rows, scored on its own framework (<code>ADVISOR</code>); it does not replace those pillar rules, and an Advisor finding can appear in both.</p>',29)])])}const p=t(d,[["render",i]]);export{u as __pageData,p as default};
